INSERT INTO t_p71821556_real_estate_catalog_.districts (name, slug, city, description, sort_order, parent_id, is_okrug, is_active)
VALUES
('Парк Победы', 'park-pobedy', 'Краснодар', 'Парк Победы — престижный жилой район с активным жилищным строительством и развитой рекреационной зоной. Близость парка формирует высокий пешеходный трафик и стабильный интерес семейной аудитории. Район привлекателен для кафе и ресторанов, детских клубов, фитнес-студий, магазинов у дома и салонов красоты. Новые жилые комплексы обеспечивают приток платёжеспособных жителей. Хорошая транспортная доступность и благоустроенная территория повышают привлекательность коммерческих помещений на первых этажах. Подходит для бизнеса, ориентированного на качественный сервис и семейный формат отдыха.', 640, NULL, FALSE, TRUE),

('Тополиный', 'topolinyy', 'Краснодар', 'Тополиный — растущий жилой массив с активной застройкой новыми жилыми комплексами. Приток новых жителей формирует спрос на товары повседневного пользования и базовые услуги. Актуальны продуктовые магазины, аптеки, детские центры, парикмахерские и бытовой сервис. Коммерческие помещения в новостройках предлагаются на выгодных стартовых условиях. Район перспективен для раннего входа с расчётом на дальнейший рост числа жителей. Подходит для локальных и сетевых операторов розничной торговли.', 650, NULL, FALSE, TRUE),

('ЖМ Демьяна Бедного', 'zhm-demyana-bednogo', 'Краснодар', 'Жилой массив Демьяна Бедного — активно застраиваемый район с современными жилыми комплексами. Растущее население формирует устойчивый спрос на товары и услуги повседневного спроса. Востребованы продуктовые магазины, аптеки, кофейни, детские центры и бытовой сервис. Коммерческие площади на первых этажах новостроек сдаются на конкурентных условиях. Удобная транспортная связь с соседними районами повышает привлекательность локации. Хороший вариант для бизнеса, рассчитывающего на дальнейший рост жилого фонда района.', 660, NULL, FALSE, TRUE),

('Парковый', 'parkovyy', 'Краснодар', 'Парковый — жилой район с благоустроенной территорией и близостью к зелёным зонам. Спокойная жилая застройка создаёт стабильный локальный спрос на товары и услуги повседневного пользования. Подходит для магазинов у дома, аптек, детских студий, парикмахерских и небольших кафе. Умеренные арендные ставки делают район доступным для начинающего бизнеса. Хорошая транспортная доступность и развивающаяся инфраструктура повышают долгосрочную привлекательность локации.', 670, NULL, FALSE, TRUE),

('отд. ОПХ Колос', 'otd-opkh-kolos', 'Краснодар', 'Отделение ОПХ Колос — пригородная территория с сельскохозяйственной специализацией и малоэтажной застройкой. Подходит для размещения складских и производственных объектов, сельскохозяйственного сервиса и мелкого агробизнеса. Земельные участки и хозяйственные постройки доступны по низким арендным ставкам. Удалённость от плотной городской застройки создаёт возможности для хранения техники, сырья и продукции. Перспективен для бизнеса, связанного с агропромышленным сектором и логистикой сельхозпродукции.', 680, NULL, FALSE, TRUE),

('отд. ОПХ КИИСХ', 'otd-opkh-kiish', 'Краснодар', 'Отделение ОПХ КИИСХ — пригородная зона с сельскохозяйственной инфраструктурой и невысокой плотностью застройки. Территория подходит для складского хранения, сельскохозяйственного производства и технического обслуживания агротехники. Низкие арендные ставки на землю и хозяйственные строения — преимущество для бизнеса с ограниченным бюджетом. Удобно для компаний, работающих с сельхозпродукцией и нуждающихся в площадях за пределами плотной городской застройки.', 690, NULL, FALSE, TRUE),

('отд. АФ Солнечная', 'otd-af-solnechnaya', 'Краснодар', 'Отделение АФ Солнечная — пригородная территория с преимущественно сельскохозяйственным назначением земель. Подходит для размещения складов, хозяйственных построек и мелкого агропроизводства. Доступные арендные ставки на землю и строения привлекательны для бизнеса, связанного с хранением и переработкой сельхозпродукции. Удалённость от центра компенсируется низкой стоимостью аренды и возможностью размещения крупногабаритных объектов.', 700, NULL, FALSE, TRUE),

('Учхоз Кубань', 'uchhoz-kuban', 'Краснодар', 'Учхоз Кубань — пригородный район с сельскохозяйственной специализацией и частной малоэтажной застройкой. Территория подходит для складского хранения, небольшого производства и сельскохозяйственного сервиса. Земельные участки предлагаются по низким арендным ставкам. Спокойная застройка формирует локальный спрос на базовые товары и услуги для местных жителей. Подходит для бизнеса, ориентированного на хранение, переработку сельхозпродукции и обслуживание аграрного сектора.', 710, NULL, FALSE, TRUE),

('Елизаветинская ст.', 'elizavetinskaya-st', 'Краснодар', 'Станица Елизаветинская — пригородный населённый пункт с частной застройкой и сельскохозяйственными угодьями. Подходит для магазинов у дома, хозяйственных товаров, автосервисов и небольших сельскохозяйственных производств. Низкие арендные ставки на землю и помещения привлекательны для локального бизнеса. Удобная транспортная связь с городом делает станицу удобной для логистики и хранения продукции. Перспективна для бизнеса, ориентированного на сельскую и пригородную аудиторию.', 720, NULL, FALSE, TRUE),

('Пашковская переправа', 'pashkovskaya-pereprava', 'Краснодар', 'Пашковская переправа — транспортный узел с высоким транзитным трафиком через реку Кубань. Подходит для автосервисов, шиномонтажей, придорожных кафе и торговых точек, ориентированных на проезжающий транспорт. Стабильный поток автомобилей формирует спрос на сопутствующие услуги и товары. Умеренные арендные ставки при высокой проходимости делают локацию привлекательной для бизнеса, работающего с транзитной аудиторией.', 730, NULL, FALSE, TRUE),

('Родные просторы', 'rodnye-prostory', 'Краснодар', 'Родные просторы — новый жилой район с активным жилищным строительством на окраине города. Приток новых жителей формирует растущий спрос на товары повседневного пользования и базовые услуги. Актуальны продуктовые магазины, аптеки, детские центры и предприятия бытового сервиса. Коммерческие помещения на старте развития района предлагаются по выгодным ставкам. Перспективен для раннего входа бизнеса с расчётом на рост населения в ближайшие годы.', 740, NULL, FALSE, TRUE)
;